import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzjeapJW.js";var i=JSON.parse(`{"title":"Review misses","description":"","frontmatter":{},"headers":[],"relativePath":"review-misses.md","filePath":"review-misses.md"}`),a={name:`review-misses.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="review-misses" tabindex="-1" dir="auto">Review misses <a class="header-anchor" href="#review-misses" aria-label="Permalink to “Review misses”">​</a></h1><p dir="auto">What the reviewers (CI, the Claude review, a person) failed to catch, and how each miss became a rule. The rules live in <code>.github/prompts/review-rules.md</code>, which the reviewer reads from the default branch, never from the PR.</p><h2 id="how-a-miss-becomes-a-rule" tabindex="-1" dir="auto">How a miss becomes a rule <a class="header-anchor" href="#how-a-miss-becomes-a-rule" aria-label="Permalink to “How a miss becomes a rule”">​</a></h2><ol><li dir="auto">Record every revert, owner-rejected change or bug found after merge below.</li><li dir="auto">A pattern becomes a rule when it appears in <strong>at least two</strong> entries and a reader can see its trigger in a diff.</li><li dir="auto">Propose the rule in a PR that changes <code>review-rules.md</code>. The owner reviews and approves it. One check per rule; a vague rule is dropped.</li><li dir="auto">Prune on a routine (monthly): delete rules that never matched, merge duplicates, and remove misses a rule now covers.</li></ol><p dir="auto">Flaky tests get the same treatment: no skip, sleep or retry. Find the root cause, or delete the test and record why here.</p><h2 id="log" tabindex="-1" dir="auto">Log <a class="header-anchor" href="#log" aria-label="Permalink to “Log”">​</a></h2><table tabindex="0"><thead><tr><th dir="auto">Date</th><th dir="auto">Change</th><th dir="auto">What was missed</th><th dir="auto">Rule</th></tr></thead><tbody><tr><td dir="auto">2026-11-26</td><td dir="auto">PR #141 (privacy leak)</td><td dir="auto">The run summary copied free-text SDK fields (<code>result</code>, <code>errors[]</code> text) and enum fields (<code>subtype</code>, <code>stop_reason</code>, <code>terminal_reason</code>) verbatim, so private text or a registered secret could reach the output. Fixed in a5697d4: only <code>error_count</code> is kept, enum fields are allowlisted with an <code>[unrecognized]</code> placeholder, <code>api_error_status</code> is numeric only, and both leak paths have tests.</td><td dir="auto">Copying external or SDK response fields into logs or a summary needs an allowlist and a leak test (provisional)</td></tr></tbody></table><p dir="auto">Provisional until a second miss confirms the pattern.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};